import{_ as l,o as a,c as i,a2 as r}from"./chunks/framework.CdvW4CUT.js";const c=JSON.parse('{"title":"資源服","description":"資源服的相關介紹。","frontmatter":{"title":"資源服","description":"資源服的相關介紹。"},"headers":[],"relativePath":"server/res/index.md","filePath":"server/res.md"}'),t={name:"server/res/index.md"};function o(h,e,d,b,n,s){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="資源服-res" tabindex="-1">資源服 res <a class="header-anchor" href="#資源服-res" aria-label="Permalink to &quot;資源服 res&quot;">​</a></h1><p><font size="4" color="green"><b>採集資源</b></font> <font size="4" color="red"><b>定期洗白</b></font></p><ul><li>不建議在資源服蓋長期性建築(洗白前1週會公告) <ul><li>建議前往<a href="/server/sv/">主伺服(sv)</a>或<a href="/server/mh/">設施服(mh)</a></li></ul></li></ul><h2 id="前往方式" tabindex="-1">前往方式 <a class="header-anchor" href="#前往方式" aria-label="Permalink to &quot;前往方式&quot;">​</a></h2><ul><li>從<a href="/server/Lobby/">大廳服(Lobby)</a>的分流傳送門前往</li><li>使用<code>/home</code>或<code>/back</code>傳送到位於該分流的紀錄點</li></ul><h2 id="分流設定" tabindex="-1">分流設定 <a class="header-anchor" href="#分流設定" aria-label="Permalink to &quot;分流設定&quot;">​</a></h2><h3 id="基本設定" tabindex="-1">基本設定 <a class="header-anchor" href="#基本設定" aria-label="Permalink to &quot;基本設定&quot;">​</a></h3><ul><li>地圖<font color="red"><b>沒有防爆</b></font></li><li>防噴裝、死亡扣除部分經驗 <ul><li>死亡時扣除5等 <ul><li>玩家經驗等級在10等以下時不扣除經驗</li></ul></li></ul></li></ul><h3 id="特殊設定" tabindex="-1">特殊設定 <a class="header-anchor" href="#特殊設定" aria-label="Permalink to &quot;特殊設定&quot;">​</a></h3><ul><li><font color="red"><b>沒有鎖箱/鎖門</b></font><ul><li>請自行保管好重要資產</li></ul></li><li><font color="red"><b>不會記錄在地獄的TNT破壞紀錄</b></font><ul><li>請勿將資產長時間置於地獄</li></ul></li><li><b>唯一</b>可以召喚終界龍的分流 <ul><li>請勿將終界主島占為己有</li></ul></li><li><b>唯一</b>會生成夜魅的分流</li><li><b>唯一</b>會生成魚的分流</li><li><b>唯一</b>伏聆觸媒會蔓延的分流</li><li><b>唯一</b>可以挖掘地獄的遠古遺骸的分流</li><li>擊殺生物有一定機率掉落生物頭顱 <ul><li>詳細掉落機率請見<a href="https://gist.github.com/MiunaPA/2c39439c94f263a1c22829800140e24e" target="_blank" rel="noreferrer">連結</a>(伺服GitHub，英文)</li></ul></li><li>在資源服擊殺終界龍時，將會給予<b>最終擊殺者</b>一個鞘翅 <ul><li>若該玩家背包無空位時，鞘翅會出現在最終擊殺者的位置上</li><li>無法判定最終擊殺者時，鞘翅會生成在終界本島中間-返回傳送門的柱子上(生成時系統會強制清除該位置的方塊)</li></ul></li></ul><h3 id="邊界大小" tabindex="-1">邊界大小 <a class="header-anchor" href="#邊界大小" aria-label="Permalink to &quot;邊界大小&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分流</th><th>主世界</th><th>地獄</th><th>終界</th></tr></thead><tbody><tr><td>資源(res)</td><td>+-50000</td><td>+-20000</td><td>+-100000</td></tr></tbody></table><h2 id="切換世界-分流方式" tabindex="-1">切換世界/分流方式 <a class="header-anchor" href="#切換世界-分流方式" aria-label="Permalink to &quot;切換世界/分流方式&quot;">​</a></h2><h3 id="切換世界" tabindex="-1">切換世界 <a class="header-anchor" href="#切換世界" aria-label="Permalink to &quot;切換世界&quot;">​</a></h3><ul><li>前往地獄請自行找地方蓋地獄門</li><li>前往終界請輸入<code>/spawn</code>回到分流重生點後由傳送門前往</li></ul><h3 id="切換分流" tabindex="-1">切換分流 <a class="header-anchor" href="#切換分流" aria-label="Permalink to &quot;切換分流&quot;">​</a></h3><ul><li>前往<a href="/server/Lobby/">大廳服(Lobby)</a><ul><li>輸入<code>bs</code>後點選指南針前往</li></ul></li><li>前往其他分流 商店街 美術館 <ul><li>請切換至<a href="/server/Lobby/">大廳服(Lobby)</a>後由各分流傳送門前往</li></ul></li></ul>',17)])])}const f=l(t,[["render",o]]);export{c as __pageData,f as default};
